import{El as s$1,Tl as r$1}from"./main-BNJ4P544.js";var i={eyebrow:`Mastodon starter kit`,openApp:`Open Mawkingbird`,hub:`All communities`,tagsHeading:`Hashtags worth following`,tagsIntro:`On Mastodon you can follow a hashtag like a person: its posts arrive in your Home feed. These are the busiest ones for this topic. Open one to read it now, no account needed.`,englishTag:`English`,futureHeading:`Help start these hashtags`,futureIntro:`Busy English hashtags have local versions that are only getting started. Follow one alongside the English tag and use it when you post in this language: that is how a tag grows.`,futureBeside:e=>`the local version of #${e}`,futureNew:`new`,futureStarting:`just starting`,caution:{spam:`Often busy with sales posts: read it before you follow.`,"off-topic":`Often used for other things: read it before you follow.`},shelves:{youtube:{heading:`Creators with a YouTube channel`,intro:`People who make videos on YouTube and post on Mastodon too.`},notable:{heading:`Writers, artists and well-known names`,intro:`Public figures in the field: authors, artists, editors, magazines and events.`},community:{heading:`Community voices`,intro:`Active people who talk about the topic and asked to be discoverable.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2,500+ followers`,"followers-625":`625+ followers`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Website`},youtube:e=>e?`YouTube channel, ${e} subscribers`:`YouTube channel`,feedCopy:`posts its new videos`,activity:e=>`${e.toLocaleString(`en`)} posts this week on mastodon.social`,serversHeading:`Where the community gathers`,serversIntro:`Any Mastodon server can follow anyone, so you can stay where you are. If you want a server built around this topic, these are good places to start.`,chooseHeading:`How we choose`,choose:[`People are listed when they asked their server to make them discoverable, or when they are public figures with public evidence: a Wikipedia or Wikidata entry, a YouTube channel with 10,000 subscribers, or 2,500 followers on Mastodon.`,`An account that looks like it wants to stay out of view is left out: few followers, hidden follower lists, no profile picture, together with a request not to be indexed. Anyone who turns off discoverability is never listed.`,`A language model checks that each person really posts about the topic, quoting their own posts as evidence. Every account is checked again each month: quiet accounts drop off and come back when they post again.`],helpHeading:`Need help?`,help:`Questions, or listed here and would rather not be? Message us on Mastodon and you will be removed for good.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Questions`,readTag:e=>`Read #${e} in Mawkingbird`,peopleHeading:`People to follow`,groupColumn:`Group`,countColumn:`People`,everyone:`Everyone`,alsoYoutubeHeading:`Also on YouTube`,alsoYoutubeIntro:(e,a)=>`${e} of the ${a} people above also make videos on YouTube. Follow them on Mastodon, subscribe to their channels in Mawkingbird to see new videos without a YouTube account, or both.`,otherLanguages:`This page in other languages`,updated:e=>`Updated ${e}`};var t={eyebrow:`Mastodon-Starterkit`,openApp:`Mawkingbird öffnen`,hub:`Alle Communities`,tagsHeading:`Hashtags, denen du folgen kannst`,tagsIntro:`Auf Mastodon kannst du einem Hashtag folgen wie einer Person: Seine Beiträge erscheinen auf deiner Startseite. Das hier sind die aktivsten zum Thema. Öffne einen und lies sofort mit, auch ohne Konto.`,englishTag:`Englisch`,futureHeading:`Hilf mit, diese Hashtags zu starten`,futureIntro:`Zu aktiven englischen Hashtags gibt es deutsche Versionen, die gerade erst anfangen. Folge einer neben dem englischen Tag und benutze sie, wenn du auf Deutsch schreibst. So wächst ein Hashtag.`,futureBeside:e=>`deutsche Version von #${e}`,futureNew:`neu`,futureStarting:`fängt gerade an`,caution:{spam:`Oft voller Verkaufsbeiträge: Lies erst rein, bevor du folgst.`,"off-topic":`Wird oft für anderes benutzt: Lies erst rein, bevor du folgst.`},shelves:{youtube:{heading:`Creator mit YouTube-Kanal`,intro:`Leute, die Videos auf YouTube machen und auch auf Mastodon schreiben.`},notable:{heading:`Autorinnen, Künstler und bekannte Namen`,intro:`Öffentliche Personen aus dem Fach: Autorinnen und Autoren, Künstler, Verlage, Magazine und Veranstaltungen.`},community:{heading:`Stimmen aus der Community`,intro:`Aktive Leute, die über das Thema schreiben und auffindbar sein wollen.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2.500+ Follower`,"followers-625":`625+ Follower`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Website`},youtube:e=>e?`YouTube-Kanal, ${e} Abos`:`YouTube-Kanal`,feedCopy:`teilt neue Videos`,activity:e=>`${e.toLocaleString(`de`)} Beitr\xE4ge diese Woche auf mastodon.social`,serversHeading:`Wo sich die Community trifft`,serversIntro:`Jeder Mastodon-Server kann allen folgen, du kannst also bleiben, wo du bist. Wenn du einen Server suchst, der sich um dieses Thema dreht, sind diese ein guter Anfang.`,chooseHeading:`Wie wir auswählen`,choose:[`Aufgenommen wird, wer seinen Server gebeten hat, ihn auffindbar zu machen, oder wer eine öffentliche Person ist, belegt durch einen Eintrag in Wikipedia oder Wikidata, einen YouTube-Kanal mit 10.000 Abos oder mindestens 625 Follower bei einem klar deutschsprachigen Mastodon-Konto.`,`Wer erkennbar unbemerkt bleiben will, bleibt draußen: wenige Follower, versteckte Follower-Listen, kein Profilbild, zusammen mit der Bitte, nicht indexiert zu werden. Wer die Auffindbarkeit abschaltet, wird nie aufgenommen.`,`Ein Sprachmodell prüft, ob jemand wirklich über das Thema schreibt, und belegt das mit Zitaten aus den eigenen Beiträgen. Jedes Konto wird jeden Monat neu geprüft: Stille Konten fallen heraus und kommen zurück, sobald sie wieder schreiben.`],helpHeading:`Brauchst du Hilfe?`,help:`Fragen, oder du stehst hier und möchtest das nicht? Schreib uns auf Mastodon, dann wirst du dauerhaft entfernt.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Fragen`,readTag:e=>`#${e} in Mawkingbird lesen`,peopleHeading:`Leute zum Folgen`,groupColumn:`Gruppe`,countColumn:`Leute`,everyone:`Alle`,alsoYoutubeHeading:`Auch auf YouTube`,alsoYoutubeIntro:(e,a)=>`${e} der ${a} Leute oben machen auch Videos auf YouTube. Folge ihnen auf Mastodon, abonniere ihre Kan\xE4le in Mawkingbird, um neue Videos ohne YouTube-Konto zu sehen, oder beides.`,otherLanguages:`Diese Seite in anderen Sprachen`,updated:e=>`Stand: ${e}`};var s={eyebrow:`Kit de démarrage Mastodon`,openApp:`Ouvrir Mawkingbird`,hub:`Toutes les communautés`,tagsHeading:`Des hashtags à suivre`,tagsIntro:`Sur Mastodon, tu peux suivre un hashtag comme une personne\xA0: ses messages arrivent dans ton fil d’accueil. Voici les plus actifs sur ce sujet. Ouvre-en un pour le lire tout de suite, sans compte.`,englishTag:`anglais`,futureHeading:`Aide à lancer ces hashtags`,futureIntro:`Les hashtags anglais les plus actifs ont des versions françaises qui démarrent à peine. Suis-en une à côté du tag anglais et utilise-la quand tu écris en français\xA0: c’est comme ça qu’un hashtag grandit.`,futureBeside:e=>`version fran\xE7aise de #${e}`,futureNew:`nouveau`,futureStarting:`démarre à peine`,caution:{spam:`Souvent envahi de messages de vente\xA0: lis-le avant de le suivre.`,"off-topic":`Souvent utilisé pour autre chose\xA0: lis-le avant de le suivre.`},shelves:{youtube:{heading:`Créateurs avec une chaîne YouTube`,intro:`Des gens qui font des vidéos sur YouTube et publient aussi sur Mastodon.`},notable:{heading:`Autrices, artistes et noms connus`,intro:`Des figures publiques du domaine\xA0: autrices et auteurs, artistes, éditeurs, revues et festivals.`},community:{heading:`Voix de la communauté`,intro:`Des personnes actives qui parlent du sujet et ont choisi d’être découvrables.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipédia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2 500+ abonnés`,"followers-625":`625+ abonnés`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Site web`},youtube:e=>e?`Cha\xEEne YouTube, ${e} abonn\xE9s`:`Chaîne YouTube`,feedCopy:`publie ses nouvelles vidéos`,activity:e=>`${e.toLocaleString(`fr`)} messages cette semaine sur mastodon.social`,serversHeading:`Où se retrouve la communauté`,serversIntro:`N’importe quel serveur Mastodon peut suivre tout le monde, tu peux donc rester où tu es. Si tu cherches un serveur dédié à ce sujet, ceux-ci sont un bon point de départ.`,chooseHeading:`Comment nous choisissons`,choose:[`Une personne apparaît ici si elle a demandé à son serveur de la rendre découvrable, ou si c’est une figure publique avec des preuves publiques\xA0: une fiche Wikipédia ou Wikidata, une chaîne YouTube de 10 000 abonnés, ou au moins 625 abonnés pour un compte Mastodon clairement francophone.`,`Un compte qui semble vouloir rester discret est écarté\xA0: peu d’abonnés, listes d’abonnés masquées, pas de photo de profil, avec une demande de non-indexation. Quiconque désactive la découvrabilité n’est jamais listé.`,`Un modèle de langage vérifie que chaque personne parle vraiment du sujet, en citant ses propres messages. Chaque compte est revérifié tous les mois\xA0: les comptes silencieux disparaissent et reviennent dès qu’ils publient à nouveau.`],helpHeading:`Besoin d’aide ?`,help:`Des questions, ou tu figures ici et tu préfères ne pas y être ? Écris-nous sur Mastodon et tu seras retiré pour de bon.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Questions`,readTag:e=>`Lire #${e} dans Mawkingbird`,peopleHeading:`Des personnes à suivre`,groupColumn:`Groupe`,countColumn:`Personnes`,everyone:`Tout le monde`,alsoYoutubeHeading:`Aussi sur YouTube`,alsoYoutubeIntro:(e,a)=>`${e} des ${a} personnes ci-dessus font aussi des vid\xE9os sur YouTube. Suis-les sur Mastodon, abonne-toi \xE0 leurs cha\xEEnes dans Mawkingbird pour voir les nouvelles vid\xE9os sans compte YouTube, ou les deux.`,otherLanguages:`Cette page dans d’autres langues`,updated:e=>`Mis \xE0 jour le ${e}`};var u={eyebrow:`Kit de inicio de Mastodon`,openApp:`Abrir Mawkingbird`,hub:`Todas las comunidades`,tagsHeading:`Etiquetas que vale la pena seguir`,tagsIntro:`En Mastodon puedes seguir una etiqueta igual que a una persona: sus publicaciones llegan a tu inicio. Estas son las más activas del tema. Abre una para leerla ya, sin cuenta.`,englishTag:`inglés`,futureHeading:`Ayuda a poner en marcha estas etiquetas`,futureIntro:`Las etiquetas en inglés más activas tienen versiones en español que apenas empiezan. Sigue una junto a la etiqueta en inglés y úsala cuando escribas en español: así crece una etiqueta.`,futureBeside:e=>`la versi\xF3n en espa\xF1ol de #${e}`,futureNew:`nueva`,futureStarting:`empezando`,caution:{spam:`Suele llenarse de anuncios de venta: léela antes de seguirla.`,"off-topic":`Se usa a menudo para otras cosas: léela antes de seguirla.`},shelves:{youtube:{heading:`Creadores con canal de YouTube`,intro:`Gente que hace vídeos en YouTube y también publica en Mastodon.`},notable:{heading:`Autoras, artistas y nombres conocidos`,intro:`Figuras públicas del género: autoras y autores, artistas, editoriales, revistas y eventos.`},community:{heading:`Voces de la comunidad`,intro:`Gente activa que habla del tema y pidió aparecer en el directorio.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2500+ seguidores`,"followers-625":`625+ seguidores`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Pódcast`,website:`Web`},youtube:e=>e?`Canal de YouTube, ${e} suscriptores`:`Canal de YouTube`,feedCopy:`publica sus vídeos nuevos`,activity:e=>`${e.toLocaleString(`es`)} publicaciones esta semana en mastodon.social`,serversHeading:`Dónde se reúne la comunidad`,serversIntro:`Cualquier servidor de Mastodon puede seguir a cualquiera, así que puedes quedarte donde estás. Si buscas un servidor dedicado a este tema, estos son un buen comienzo.`,chooseHeading:`Cómo elegimos`,choose:[`Aparece aquí quien pidió a su servidor aparecer en el directorio, o quien es una figura pública con pruebas públicas: una entrada en Wikipedia o Wikidata, un canal de YouTube con 10 000 suscriptores o al menos 625 seguidores en una cuenta de Mastodon claramente en español.`,`Si una cuenta parece querer pasar desapercibida, la dejamos fuera: pocos seguidores, listas de seguidores ocultas, sin foto de perfil, junto con la petición de no ser indexada. Quien desactiva aparecer en el directorio nunca aparece aquí.`,`Un modelo de lenguaje comprueba que cada persona habla de verdad del tema, citando sus propias publicaciones. Cada cuenta se revisa de nuevo cada mes: las cuentas inactivas salen y vuelven cuando publican otra vez.`],helpHeading:`¿Necesitas ayuda?`,help:`¿Preguntas, o apareces aquí y prefieres no estar? Escríbenos en Mastodon y te quitaremos para siempre.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Preguntas`,readTag:e=>`Leer #${e} en Mawkingbird`,peopleHeading:`Personas a seguir`,groupColumn:`Grupo`,countColumn:`Personas`,everyone:`Todos`,alsoYoutubeHeading:`También en YouTube`,alsoYoutubeIntro:(e,a)=>`${e} de las ${a} personas de arriba tambi\xE9n hacen v\xEDdeos en YouTube. S\xEDguelas en Mastodon, suscr\xEDbete a sus canales en Mawkingbird para ver los v\xEDdeos nuevos sin cuenta de YouTube, o ambas cosas.`,otherLanguages:`Esta página en otros idiomas`,updated:e=>`Actualizado el ${e}`};var r={eyebrow:`Starter kit di Mastodon`,openApp:`Apri Mawkingbird`,hub:`Tutte le comunità`,tagsHeading:`Hashtag da seguire`,tagsIntro:`Su Mastodon puoi seguire un hashtag come una persona: i suoi post arrivano nella tua home. Questi sono i più attivi sull’argomento. Aprine uno per leggerlo subito, senza account.`,englishTag:`inglese`,futureHeading:`Aiuta a far partire questi hashtag`,futureIntro:`Gli hashtag inglesi più attivi hanno versioni italiane appena nate. Seguine una accanto al tag inglese e usala quando scrivi in italiano: è così che un hashtag cresce.`,futureBeside:e=>`la versione italiana di #${e}`,futureNew:`nuovo`,futureStarting:`agli inizi`,caution:{spam:`Spesso pieno di post di vendita: leggilo prima di seguirlo.`,"off-topic":`Usato spesso per altro: leggilo prima di seguirlo.`},shelves:{youtube:{heading:`Creator con un canale YouTube`,intro:`Persone che fanno video su YouTube e scrivono anche su Mastodon.`},notable:{heading:`Autrici, artisti e nomi noti`,intro:`Figure pubbliche del genere: autrici e autori, artisti, editori, riviste ed eventi.`},community:{heading:`Voci della community`,intro:`Persone attive che parlano dell’argomento e hanno chiesto di essere trovabili.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2.500+ follower`,"followers-625":`625+ follower`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Sito web`},youtube:e=>e?`Canale YouTube, ${e} iscritti`:`Canale YouTube`,feedCopy:`pubblica i nuovi video`,activity:e=>`${e.toLocaleString(`it`)} post questa settimana su mastodon.social`,serversHeading:`Dove si ritrova la community`,serversIntro:`Ogni server Mastodon può seguire chiunque, quindi puoi restare dove sei. Se cerchi un server dedicato a questo argomento, questi sono un buon inizio.`,chooseHeading:`Come scegliamo`,choose:[`Compare qui chi ha chiesto al proprio server di essere trovabile, o chi è una figura pubblica con prove pubbliche: una voce su Wikipedia o Wikidata, un canale YouTube da 10.000 iscritti o almeno 625 follower per un account Mastodon chiaramente in italiano.`,`Un account che sembra voler restare in disparte viene escluso: pochi follower, liste dei follower nascoste, nessuna foto profilo, insieme alla richiesta di non essere indicizzato. Chi disattiva la trovabilità non compare mai.`,`Un modello linguistico verifica che ogni persona parli davvero dell’argomento, citando i suoi post. Ogni account viene ricontrollato ogni mese: gli account fermi escono e tornano quando ricominciano a scrivere.`],helpHeading:`Serve aiuto?`,help:`Domande, o compari qui e preferisci di no? Scrivici su Mastodon e verrai rimosso per sempre.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Domande`,readTag:e=>`Leggi #${e} in Mawkingbird`,peopleHeading:`Persone da seguire`,groupColumn:`Gruppo`,countColumn:`Persone`,everyone:`Tutti`,alsoYoutubeHeading:`Anche su YouTube`,alsoYoutubeIntro:(e,a)=>`${e} delle ${a} persone qui sopra fanno anche video su YouTube. Seguile su Mastodon, iscriviti ai loro canali in Mawkingbird per vedere i nuovi video senza un account YouTube, o entrambe le cose.`,otherLanguages:`Questa pagina in altre lingue`,updated:e=>`Aggiornato il ${e}`};var d={eyebrow:`Mastodon（マストドン）スターターキット`,openApp:`Mawkingbird を開く`,hub:`すべてのコミュニティ`,tagsHeading:`フォローしたいハッシュタグ`,tagsIntro:`Mastodon では、人と同じようにハッシュタグもフォローできます。フォローすると、そのタグの投稿がホームに届きます。ここにあるのは、このテーマで特に活発なタグです。開けば、アカウントがなくてもすぐに読めます。`,englishTag:`英語`,futureHeading:`このハッシュタグを一緒に育てましょう`,futureIntro:`活発な英語のハッシュタグには、まだ始まったばかりの日本語版があります。英語のタグと一緒にフォローして、日本語で投稿するときに使ってください。ハッシュタグはそうやって育ちます。`,futureBeside:e=>`#${e} \u306E\u65E5\u672C\u8A9E\u7248`,futureNew:`新しいタグ`,futureStarting:`始まったばかり`,caution:{spam:`宣伝の投稿が多いタグです。フォローする前に読んでみてください。`,"off-topic":`別の話題にもよく使われます。フォローする前に読んでみてください。`},shelves:{youtube:{heading:`YouTube チャンネルを持つクリエイター`,intro:`YouTube で動画を作り、Mastodon にも投稿している人たちです。`},notable:{heading:`作家・アーティスト・よく知られた名前`,intro:`この分野の著名人です。作家、アーティスト、出版社、雑誌、イベントなど。`},community:{heading:`コミュニティの声`,intro:`このテーマについて活発に投稿し、見つけてもらうことを選んだ人たちです。`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 1万人以上`,"followers-2500":`フォロワー 2,500 人以上`,"followers-625":`フォロワー 625 人以上`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`ポッドキャスト`,website:`ウェブサイト`},youtube:e=>e?`YouTube \u30C1\u30E3\u30F3\u30CD\u30EB\uFF08\u767B\u9332\u8005 ${e}\uFF09`:`YouTube チャンネル`,feedCopy:`新しい動画を投稿`,activity:e=>`mastodon.social \u3067\u4ECA\u9031 ${e.toLocaleString(`ja`)} \u4EF6\u306E\u6295\u7A3F`,serversHeading:`コミュニティが集まる場所`,serversIntro:`Mastodon はどのサーバーからでも誰でもフォローできるので、今のサーバーのままで大丈夫です。このテーマのサーバーを探しているなら、ここから始めるのがおすすめです。`,chooseHeading:`選び方`,choose:[`ここに載るのは、自分のサーバーで「見つけてもらう」設定をオンにした人か、公開された根拠がある著名人です。根拠とは、Wikipedia や Wikidata の項目、登録者 1 万人以上の YouTube チャンネル、日本語で発信していることが確認できる Mastodon アカウントのフォロワー 625 人以上のいずれかです。`,`目立たずにいたいように見えるアカウントは載せません。フォロワーが少ない、フォロー・フォロワー一覧を隠している、プロフィール画像がない、といった点に加えて検索エンジンに載せない設定をしている場合です。「見つけてもらう」設定をオフにしている人は決して載りません。`,`言語モデルが、その人が本当にこのテーマについて投稿しているかを、本人の投稿を引用して確かめます。すべてのアカウントは毎月見直します。投稿が止まったアカウントは外れ、また投稿を始めれば戻ります。`],helpHeading:`お困りですか？`,help:`ご質問、またはここに載りたくない場合は、Mastodon でご連絡ください。今後も載らないよう削除します。`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`よくある質問`,readTag:e=>`#${e} \u3092 Mawkingbird \u3067\u8AAD\u3080`,peopleHeading:`フォローしたい人`,groupColumn:`グループ`,countColumn:`人数`,everyone:`全員`,alsoYoutubeHeading:`YouTube にもいる人`,alsoYoutubeIntro:(e,a)=>`\u4E0A\u306E ${a} \u4EBA\u306E\u3046\u3061 ${e} \u4EBA\u306F YouTube \u3067\u3082\u52D5\u753B\u3092\u6295\u7A3F\u3057\u3066\u3044\u307E\u3059\u3002\u30DE\u30B9\u30C8\u30C9\u30F3\uFF08Mastodon\uFF09\u3067\u30D5\u30A9\u30ED\u30FC\u3059\u308B\u3053\u3068\u3082\u3001YouTube \u30A2\u30AB\u30A6\u30F3\u30C8\u306A\u3057\u3067\u65B0\u3057\u3044\u52D5\u753B\u3092\u898B\u3089\u308C\u308B\u3088\u3046 Mawkingbird \u3067\u30C1\u30E3\u30F3\u30CD\u30EB\u3092\u767B\u9332\u3059\u308B\u3053\u3068\u3082\u3001\u4E21\u65B9\u3059\u308B\u3053\u3068\u3082\u3067\u304D\u307E\u3059\u3002`,otherLanguages:`ほかの言語のページ`,updated:e=>`${e} \u66F4\u65B0`};var l={eyebrow:`Kit permulaan Mastodon`,openApp:`Buka Mawkingbird`,hub:`Semua komuniti`,tagsHeading:`Hashtag untuk diikuti`,tagsIntro:`Ikuti hashtag untuk melihat siarannya dalam suapan Utama. Buka hashtag untuk membaca tanpa akaun.`,englishTag:`Bahasa Inggeris`,futureHeading:`Bantu mulakan hashtag ini`,futureIntro:`Gunakan hashtag tempatan bersama hashtag bahasa Inggeris untuk membantu komuniti berkembang.`,futureBeside:e=>`versi tempatan #${e}`,futureNew:`baharu`,futureStarting:`baru bermula`,caution:{spam:`Banyak siaran jualan: baca dahulu sebelum mengikuti.`,"off-topic":`Sering digunakan untuk topik lain: baca dahulu.`},shelves:{youtube:{heading:`Pencipta dengan saluran YouTube`,intro:`Pencipta video yang turut berkongsi di Mastodon.`},notable:{heading:`Penulis, seniman dan tokoh dikenali`,intro:`Akaun awam yang berkongsi tentang topik ini.`},community:{heading:`Suara komuniti`,intro:`Akaun komuniti untuk diterokai, termasuk yang jarang menulis.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2,500+ pengikut`,"followers-625":`625+ pengikut`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Laman web`},youtube:e=>e?`Saluran YouTube, ${e} pelanggan`:`Saluran YouTube`,feedCopy:`berkongsi video baharu`,activity:e=>`${e.toLocaleString(`ms`)} siaran minggu ini di mastodon.social`,serversHeading:`Tempat komuniti berkumpul`,serversIntro:`Anda boleh mengikuti akaun dari mana-mana pelayan Mastodon tanpa berpindah pelayan.`,chooseHeading:`Cara kami memilih`,choose:[`Kit komuniti kecil ini merangkumi akaun dengan kaitan setempat yang kelihatan dalam profil atau siaran awam. Tiada jumlah minimum pengikut atau siaran; akaun dengan siaran dalam tempoh 30 bulan lalu boleh disertakan.`,`Kami menghormati permintaan supaya profil tidak diindeks di web dan pilihan untuk tidak ditemui. Mematikan carian teks penuh Mastodon sahaja tidak menghalang penyenaraian di sini.`,`Kandungan disemak untuk kesesuaian keluarga dan kegunaan kepada pembaca. Bahasa dan kekerapan siaran berbeza-beza. Pratonton sebelum mengikuti; suapan mungkin berubah selepas semakan.`],helpHeading:`Perlukan bantuan?`,help:`Ada soalan atau mahu dikeluarkan daripada senarai? Hubungi kami di Mastodon; permintaan anda akan dihormati.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Soalan lazim`,readTag:e=>`Baca #${e} di Mawkingbird`,peopleHeading:`Akaun untuk diikuti`,groupColumn:`Kumpulan`,countColumn:`Akaun`,everyone:`Semua`,alsoYoutubeHeading:`Juga di YouTube`,alsoYoutubeIntro:(e,a)=>`${e} daripada ${a} akaun ini turut menghasilkan video di YouTube. Ikuti di Mastodon atau langgan saluran mereka di Mawkingbird.`,otherLanguages:`Halaman ini dalam bahasa lain`,updated:e=>`Dikemas kini ${e}`};var g={eyebrow:`Bộ khởi đầu Mastodon`,openApp:`Mở Mawkingbird`,hub:`Tất cả cộng đồng`,tagsHeading:`Hashtag để theo dõi`,tagsIntro:`Theo dõi hashtag để xem bài viết trong bảng tin. Bạn có thể đọc mà không cần tài khoản.`,englishTag:`Tiếng Anh`,futureHeading:`Cùng phát triển hashtag`,futureIntro:`Dùng hashtag tiếng Việt cùng hashtag tiếng Anh để giúp cộng đồng phát triển.`,futureBeside:e=>`phi\xEAn b\u1EA3n ti\u1EBFng Vi\u1EC7t c\u1EE7a #${e}`,futureNew:`mới`,futureStarting:`vừa bắt đầu`,caution:{spam:`Nhiều bài bán hàng: hãy đọc trước khi theo dõi.`,"off-topic":`Thường dùng cho chủ đề khác: hãy đọc trước.`},shelves:{youtube:{heading:`Nhà sáng tạo có kênh YouTube`,intro:`Những người làm video cũng chia sẻ trên Mastodon.`},notable:{heading:`Tác giả, nghệ sĩ và gương mặt quen thuộc`,intro:`Tài khoản công khai chia sẻ về chủ đề này.`},community:{heading:`Tiếng nói cộng đồng`,intro:`Những tài khoản để khám phá, kể cả người ít đăng bài.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2.500+ người theo dõi`,"followers-625":`625+ người theo dõi`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Trang web`},youtube:e=>e?`K\xEAnh YouTube, ${e} ng\u01B0\u1EDDi \u0111\u0103ng k\xFD`:`Kênh YouTube`,feedCopy:`chia sẻ video mới`,activity:e=>`${e.toLocaleString(`vi`)} b\xE0i tu\u1EA7n n\xE0y tr\xEAn mastodon.social`,serversHeading:`Nơi cộng đồng gặp gỡ`,serversIntro:`Bạn có thể theo dõi tài khoản trên mọi máy chủ Mastodon mà không cần chuyển máy chủ.`,chooseHeading:`Cách chúng tôi lựa chọn`,choose:[`Tài khoản viết tiếng Việt ở bất cứ đâu đều có thể được chọn, kể cả khi không nêu nơi ở. Tài khoản viết tiếng Anh cần có mối liên hệ rõ ràng với Việt Nam.`,`Không yêu cầu số người theo dõi hay số bài tối thiểu. Tài khoản có bài trong 30 tháng qua có thể tham gia. Chúng tôi tôn trọng lựa chọn không được tìm thấy và yêu cầu không lập chỉ mục web; tắt tìm kiếm toàn văn Mastodon không tự động loại tài khoản.`,`Nội dung được xem xét về tính phù hợp với gia đình và ích lợi cho người đọc. Hãy xem trước: nội dung có thể thay đổi sau khi được chọn.`],helpHeading:`Cần trợ giúp?`,help:`Có câu hỏi hoặc muốn được gỡ khỏi danh sách? Hãy liên hệ trên Mastodon; chúng tôi sẽ tôn trọng yêu cầu của bạn.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Câu hỏi thường gặp`,readTag:e=>`\u0110\u1ECDc #${e} tr\xEAn Mawkingbird`,peopleHeading:`Tài khoản để theo dõi`,groupColumn:`Nhóm`,countColumn:`Tài khoản`,everyone:`Tất cả`,alsoYoutubeHeading:`Cũng có trên YouTube`,alsoYoutubeIntro:(e,a)=>`${e} trong ${a} t\xE0i kho\u1EA3n c\u0169ng l\xE0m video tr\xEAn YouTube. Theo d\xF5i tr\xEAn Mastodon ho\u1EB7c \u0111\u0103ng k\xFD k\xEAnh trong Mawkingbird.`,otherLanguages:`Trang này bằng ngôn ngữ khác`,updated:e=>`C\u1EADp nh\u1EADt ${e}`};var c={eyebrow:`Mastodon-startpakket`,openApp:`Mawkingbird openen`,hub:`Alle gemeenschappen`,tagsHeading:`Hashtags om te volgen`,tagsIntro:`Volg een hashtag om berichten in je tijdlijn te zien. Bekijk eerst de berichten: sommige tags zijn rustig of worden ook voor andere onderwerpen gebruikt.`,englishTag:`Engels`,futureHeading:`Help deze hashtags groeien`,futureIntro:`Gebruik een Nederlandstalige hashtag naast de Engelse om anderen te helpen elkaar te vinden.`,futureBeside:e=>`de Nederlandstalige variant van #${e}`,futureNew:`nieuw`,futureStarting:`net begonnen`,caution:{spam:`Veel verkoopberichten: bekijk de tag voordat je hem volgt.`,"off-topic":`Ook voor andere onderwerpen gebruikt: bekijk eerst de berichten.`},shelves:{youtube:{heading:`Makers met een YouTube-kanaal`,intro:`Videomakers die ook op Mastodon delen.`},notable:{heading:`Bekende stemmen en organisaties`,intro:`Publieke accounts die over dit onderwerp schrijven.`},community:{heading:`Stemmen uit de gemeenschap`,intro:`Actieve accounts die gevonden willen worden en over dit onderwerp delen.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube 10k+`,"followers-2500":`2.500+ volgers`,"followers-625":`625+ volgers`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Website`},youtube:e=>e?`YouTube-kanaal, ${e} abonnees`:`YouTube-kanaal`,feedCopy:`deelt nieuwe video’s`,activity:e=>`${e.toLocaleString(`nl`)} berichten deze week op mastodon.social`,serversHeading:`Waar de gemeenschap samenkomt`,serversIntro:`Je kunt accounts op andere Mastodon-servers volgen zonder zelf van server te wisselen.`,chooseHeading:`Hoe we kiezen`,choose:[`We bekijken openbare profielen en berichten op relevantie en bruikbaarheid. Accounts moeten recent actief zijn. De voorwaarden voor deelname staan bij het onderwerp.`,`We respecteren privacykeuzes en verzoeken om niet door webzoekmachines geïndexeerd te worden. Het uitschakelen van Mastodons eigen tekstzoekfunctie is op zichzelf geen uitsluiting.`,`Een selectie is een momentopname. Bekijk de berichten en bepaal zelf wie en wat je wilt volgen.`],helpHeading:`Hulp nodig?`,help:`Vragen of liever niet op de lijst? Neem contact op via Mastodon. We respecteren verwijderverzoeken.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Veelgestelde vragen`,readTag:e=>`Lees #${e} in Mawkingbird`,peopleHeading:`Accounts om te volgen`,groupColumn:`Groep`,countColumn:`Accounts`,everyone:`Iedereen`,alsoYoutubeHeading:`Ook op YouTube`,alsoYoutubeIntro:(e,a)=>`${e} van deze ${a} accounts maken ook YouTube-video\u2019s. Volg ze op Mastodon of abonneer je in Mawkingbird.`,otherLanguages:`Deze pagina in andere talen`,updated:e=>`Bijgewerkt op ${e}`};var h={eyebrow:`Стартова добірка Mastodon`,openApp:`Відкрити Mawkingbird`,hub:`Усі спільноти`,tagsHeading:`Тематичні хештеги`,tagsIntro:`На хештеги можна підписуватися, як на людей: дописи з ними потраплятимуть у домашню стрічку. Деякі теги поки тихі. Відкрий тег і переглянь його перед підпискою.`,englishTag:`Англійською`,futureHeading:`Допоможи розвинути ці хештеги`,futureIntro:`Місцеві відповідники популярних англійських хештегів лише набирають обертів. Використовуй їх у дописах українською, щоб іншим було легше знайти тему.`,futureBeside:e=>`\u043C\u0456\u0441\u0446\u0435\u0432\u0438\u0439 \u0432\u0456\u0434\u043F\u043E\u0432\u0456\u0434\u043D\u0438\u043A #${e}`,futureNew:`новий`,futureStarting:`на початку`,caution:{spam:`У вибірці багато рекламних дописів. Переглянь перед підпискою.`,"off-topic":`Тег часто використовують поза темою. Переглянь перед підпискою.`},shelves:{youtube:{heading:`Автори з каналами YouTube`,intro:`Автори, які також публікують відео на YouTube.`},notable:{heading:`Відомі автори й організації`,intro:`Публічні автори, видання та організації цієї тематики.`},community:{heading:`Учасники спільноти`,intro:`Люди, які пишуть на цю тему й дозволяють рекомендувати свій профіль.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube: 10 тис.+`,"followers-2500":`2500+ підписників`,"followers-625":`625+ підписників`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Подкаст`,website:`Сайт`},youtube:e=>e?`\u041A\u0430\u043D\u0430\u043B YouTube, \u043F\u0456\u0434\u043F\u0438\u0441\u043D\u0438\u043A\u0456\u0432: ${e}`:`Канал YouTube`,feedCopy:`публікує нові відео`,activity:e=>`\u0414\u043E\u043F\u0438\u0441\u0456\u0432 \u0437\u0430 \u0442\u0438\u0436\u0434\u0435\u043D\u044C \u043D\u0430 mastodon.social: ${e.toLocaleString(`uk`)}`,serversHeading:`Де спілкується спільнота`,serversIntro:`З будь-якого сервера Mastodon можна підписуватися на інших. Якщо обираєш сервер, придивись до цих спільнот та їхніх правил.`,chooseHeading:`Як ми обираємо`,choose:[`Перевіряємо публічні дописи за темою та мовою. Невеликі акаунти, які дозволяють рекомендувати свій профіль, також можуть потрапити до добірки.`,`Поважаємо явну заборону рекомендувати профіль, заборону вебіндексації та прохання про видалення. Налаштування внутрішнього повнотекстового пошуку Mastodon розглядаємо окремо.`,`Для невеликих мовних спільнот допускаємо рідші дописи й меншу добірку. Це не скасовує перевірок тематики, змісту та приватності. Деталі активності наведені в описі теми.`],helpHeading:`Потрібна допомога?`,help:`Маєш запитання або хочеш прибрати свій акаунт із добірки? Напиши нам у Mastodon.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Запитання`,readTag:e=>`\u0427\u0438\u0442\u0430\u0442\u0438 #${e} \u0443 Mawkingbird`,peopleHeading:`На кого підписатися`,groupColumn:`Група`,countColumn:`Акаунти`,everyone:`Усі`,alsoYoutubeHeading:`Також на YouTube`,alsoYoutubeIntro:(e,a)=>`\u0421\u0435\u0440\u0435\u0434 ${a} \u0430\u043A\u0430\u0443\u043D\u0442\u0456\u0432 \u0454 ${e} \u0437 \u043A\u0430\u043D\u0430\u043B\u0430\u043C\u0438 YouTube. \u041C\u043E\u0436\u043D\u0430 \u043F\u0456\u0434\u043F\u0438\u0441\u0430\u0442\u0438\u0441\u044F \u043D\u0430 \u043D\u0438\u0445 \u0443 Mastodon \u0430\u0431\u043E \u0434\u0438\u0432\u0438\u0442\u0438\u0441\u044F \u043D\u043E\u0432\u0456 \u0432\u0456\u0434\u0435\u043E \u0447\u0435\u0440\u0435\u0437 Mawkingbird.`,otherLanguages:`Ця сторінка іншими мовами`,updated:e=>`\u041E\u043D\u043E\u0432\u043B\u0435\u043D\u043E: ${e}`};var p={eyebrow:`Mastodon sākuma komplekts`,openApp:`Atvērt Mawkingbird`,hub:`Visas kopienas`,tagsHeading:`Tēmturi, kuriem sekot`,tagsIntro:`Mastodon var sekot arī tēmturiem. To publiskie ieraksti parādās tavā mājas plūsmā. Šeit ir tēmai noderīgi tēmturi; daži ir klusi. Atver tos un apskati ierakstus pirms sekošanas.`,englishTag:`Angliski`,futureHeading:`Palīdzi tēmturiem iedzīvoties`,futureIntro:`Dažiem plaši lietotiem angļu tēmturiem ir vietējie varianti, kuri vēl tikai sāk veidoties. Seko abiem un lieto vietējo tēmturi savos ierakstos.`,futureBeside:e=>`t\u0113mtura #${e} viet\u0113jais variants`,futureNew:`jauns`,futureStarting:`sāk iedzīvoties`,caution:{spam:`Te mēdz būt daudz reklāmu. Apskati ierakstus pirms sekošanas.`,"off-topic":`Šo tēmturi izmanto arī citām tēmām. Vispirms apskati ierakstus.`},shelves:{youtube:{heading:`Autori ar YouTube kanālu`,intro:`Video autori, kuri raksta arī Mastodon.`},notable:{heading:`Autori un pazīstami vārdi`,intro:`Šīs tēmas autori, mākslinieki, izdevumi un organizācijas.`},community:{heading:`Kopienas balsis`,intro:`Aktīvi cilvēki, kuri raksta par tēmu un ļauj atrast savu profilu.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube: 10 tūkst.+`,"followers-2500":`2500+ sekotāju`,"followers-625":`625+ sekotāju`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Raidieraksts`,website:`Tīmekļvietne`},youtube:e=>e?`YouTube kan\u0101ls, abonenti: ${e}`:`YouTube kanāls`,feedCopy:`publicē savus jaunos video`,activity:e=>`${e.toLocaleString(`lv`)} ieraksti \u0161oned\u0113\u013C vietn\u0113 mastodon.social`,serversHeading:`Kur pulcējas kopiena`,serversIntro:`No sava Mastodon servera vari sekot cilvēkiem citos serveros. Ja vēl izvēlies serveri, iepazīsties ar šīm kopienām un to noteikumiem.`,chooseHeading:`Kā veidojam izlasi`,choose:[`Pārbaudām nesenos publiskos ierakstus, tēmu un valodu. Iekļaujam profilus, kuru autori ir atļāvuši to atrašanu, vai publiski pazīstamus autorus ar pārbaudāmu atpazīstamības pamatu.`,`Neiekļaujam bloķētus vai pārceltus profilus un ievērojam skaidru atteikumu no profila ieteikšanas un izņemšanas lūgumus. Ņemam vērā arī privātuma signālus.`,`Valodas modelis palīdz pārbaudīt atbilstību pēc pašu autoru ierakstiem. Izlasi pārskata pirms publicēšanas; tā negarantē, ka visi turpmākie ieraksti būs par tēmu.`],helpHeading:`Vajadzīga palīdzība?`,help:`Vai ir jautājumi, vai vēlies izņemt savu profilu no izlases? Raksti mums Mastodon.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Jautājumi`,readTag:e=>`Las\u012Bt #${e} Mawkingbird`,peopleHeading:`Kam sekot`,groupColumn:`Grupa`,countColumn:`Profili`,everyone:`Visi`,alsoYoutubeHeading:`Arī YouTube`,alsoYoutubeIntro:(e,a)=>`${e} no \u0161iem ${a} profiliem ir ar\u012B YouTube kan\u0101ls. Vari sekot autoram Mastodon, abon\u0113t kan\u0101lu Mawkingbird vai dar\u012Bt abus.`,otherLanguages:`Šī lapa citās valodās`,updated:e=>`Atjaunin\u0101ts: ${e}`};var k=s$1(r$1({},i),{eyebrow:`Αφετηρία για το Mastodon`,openApp:`Άνοιγμα Mawkingbird`,hub:`Όλες οι κοινότητες`,tagsHeading:`Hashtags που αξίζει να ακολουθήσεις`,tagsIntro:`Στο Mastodon μπορείς να ακολουθείς hashtags: οι δημόσιες αναρτήσεις τους εμφανίζονται στην αρχική σου ροή. Μερικά από αυτά είναι ήσυχα. Δες τις αναρτήσεις πριν ακολουθήσεις.`,englishTag:`Αγγλικά`,futureHeading:`Βοήθησε αυτά τα hashtags να ξεκινήσουν`,futureIntro:`Ορισμένα δημοφιλή αγγλικά hashtags έχουν τοπικές εκδοχές που μόλις ξεκινούν. Ακολούθησε και τις δύο και χρησιμοποίησε την τοπική όταν γράφεις ελληνικά.`,futureBeside:e=>`\u03B7 \u03C4\u03BF\u03C0\u03B9\u03BA\u03AE \u03B5\u03BA\u03B4\u03BF\u03C7\u03AE \u03C4\u03BF\u03C5 #${e}`,futureNew:`νέο`,futureStarting:`μόλις ξεκινά`,youtube:e=>e?`\u039A\u03B1\u03BD\u03AC\u03BB\u03B9 YouTube, \u03C3\u03C5\u03BD\u03B4\u03C1\u03BF\u03BC\u03B7\u03C4\u03AD\u03C2: ${e}`:`Κανάλι YouTube`,feedCopy:`δημοσιεύει τα νέα του βίντεο`,activity:e=>`${e.toLocaleString(`el`)} \u03B1\u03BD\u03B1\u03C1\u03C4\u03AE\u03C3\u03B5\u03B9\u03C2 \u03B1\u03C5\u03C4\u03AE \u03C4\u03B7\u03BD \u03B5\u03B2\u03B4\u03BF\u03BC\u03AC\u03B4\u03B1 \u03C3\u03C4\u03BF mastodon.social`,serversHeading:`Πού συναντιέται η κοινότητα`,serversIntro:`Μπορείς να ακολουθείς λογαριασμούς σε άλλους διακομιστές από τον δικό σου. Αν διαλέγεις τώρα διακομιστή, δες αυτές τις κοινότητες και τους κανόνες τους.`,chooseHeading:`Πώς επιλέγουμε`,helpHeading:`Χρειάζεσαι βοήθεια;`,help:`Έχεις ερωτήσεις ή θέλεις να αφαιρεθεί το προφίλ σου; Γράψε μας στο Mastodon.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Συχνές ερωτήσεις`,readTag:e=>`\u0394\u03B9\u03AC\u03B2\u03B1\u03C3\u03B5 \u03C4\u03BF #${e} \u03C3\u03C4\u03BF Mawkingbird`,peopleHeading:`Ποιον να ακολουθήσεις`,groupColumn:`Ομάδα`,countColumn:`Λογαριασμοί`,everyone:`Όλοι`,alsoYoutubeHeading:`Επίσης στο YouTube`,alsoYoutubeIntro:(e,a)=>`${e} \u03B1\u03C0\u03CC \u03C4\u03BF\u03C5\u03C2 ${a} \u03BB\u03BF\u03B3\u03B1\u03C1\u03B9\u03B1\u03C3\u03BC\u03BF\u03CD\u03C2 \u03AD\u03C7\u03BF\u03C5\u03BD \u03BA\u03B1\u03BD\u03AC\u03BB\u03B9 YouTube. \u0391\u03BA\u03BF\u03BB\u03BF\u03CD\u03B8\u03B7\u03C3\u03AD \u03C4\u03BF\u03C5\u03C2 \u03C3\u03C4\u03BF Mastodon \u03AE \u03B4\u03B5\u03C2 \u03C4\u03B1 \u03B2\u03AF\u03BD\u03C4\u03B5\u03BF \u03C3\u03C4\u03BF Mawkingbird.`,otherLanguages:`Αυτή η σελίδα σε άλλες γλώσσες`,updated:e=>`\u0395\u03BD\u03B7\u03BC\u03AD\u03C1\u03C9\u03C3\u03B7: ${e}`,caution:{spam:`Συχνές διαφημίσεις: δες το περιεχόμενο πριν ακολουθήσεις.`,"off-topic":`Χρησιμοποιείται και για άλλα θέματα. Δες πρώτα τις αναρτήσεις.`},shelves:{youtube:{heading:`Δημιουργοί με κανάλι YouTube`,intro:`Δημιουργοί βίντεο που γράφουν και στο Mastodon.`},notable:{heading:`Δημιουργοί και γνωστά ονόματα`,intro:`Συγγραφείς, καλλιτέχνες, εκδόσεις και οργανώσεις του χώρου.`},community:{heading:`Φωνές της κοινότητας`,intro:`Ενεργοί άνθρωποι που γράφουν για το θέμα και επιτρέπουν την ανακάλυψη του προφίλ τους.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube: 10 χιλ.+`,"followers-2500":`2.500+ ακόλουθοι`,"followers-625":`625+ ακόλουθοι`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Ιστότοπος`},choose:[`Ελέγχουμε πρόσφατες δημόσιες αναρτήσεις, θέμα και γλώσσα. Επιλέγουμε προφίλ που επιτρέπουν την ανακάλυψη ή δημόσια πρόσωπα με επαληθεύσιμα στοιχεία αναγνωρισιμότητας.`,`Αποκλείουμε ανενεργά ή μεταφερμένα προφίλ και σεβόμαστε τις ρητές αρνήσεις προτάσεων και τα αιτήματα αφαίρεσης. Εξετάζουμε επίσης τα σήματα ιδιωτικότητας.`,`Ένα γλωσσικό μοντέλο βοηθά στον έλεγχο με βάση τις αναρτήσεις των ίδιων των δημιουργών. Η επιλογή ελέγχεται πριν δημοσιευτεί, αλλά δεν εγγυάται το θέμα των μελλοντικών αναρτήσεων.`]});var m=s$1(r$1({},i),{eyebrow:`Mastodon-kezdőcsomag`,openApp:`Mawkingbird megnyitása`,hub:`Minden közösség`,tagsHeading:`Hashtagek, amelyeket érdemes követni`,tagsIntro:`A Mastodonon hashtageket is követhetsz: nyilvános bejegyzéseik megjelennek a kezdőlapi hírfolyamodban. Némelyik csendes lehet. Követés előtt nézz bele a bejegyzésekbe.`,englishTag:`Angol`,futureHeading:`Segíts elindítani ezeket a hashtageket`,futureIntro:`Néhány népszerű angol hashtagnek még csak most indul a helyi változata. Kövesd mindkettőt, és magyar bejegyzéseidben használd a helyi címkét.`,futureBeside:e=>`a #${e} helyi v\xE1ltozata`,futureNew:`új`,futureStarting:`most indul`,youtube:e=>e?`YouTube-csatorna, feliratkoz\xF3k: ${e}`:`YouTube-csatorna`,feedCopy:`közzéteszi új videóit`,activity:e=>`${e.toLocaleString(`hu`)} bejegyz\xE9s ezen a h\xE9ten a mastodon.social oldalon`,serversHeading:`Hol találkozik a közösség?`,serversIntro:`Saját Mastodon-szerveredről más szerverek profiljait is követheted. Ha most választasz szervert, ismerd meg ezeket a közösségeket és a szabályaikat.`,chooseHeading:`Hogyan válogatunk?`,helpHeading:`Segítségre van szükséged?`,help:`Kérdésed van, vagy szeretnéd eltávolíttatni a profilodat? Írj nekünk a Mastodonon.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Gyakori kérdések`,readTag:e=>`#${e} olvas\xE1sa a Mawkingbirdben`,peopleHeading:`Kit érdemes követni?`,groupColumn:`Csoport`,countColumn:`Profilok`,everyone:`Mindenki`,alsoYoutubeHeading:`A YouTube-on is`,alsoYoutubeIntro:(e,a)=>`A ${a} profil k\xF6z\xFCl ${e} YouTube-csatorn\xE1val is rendelkezik. K\xF6vetheted \u0151ket a Mastodonon, vagy n\xE9zheted a vide\xF3kat a Mawkingbirdben.`,otherLanguages:`Ez az oldal más nyelveken`,updated:e=>`Friss\xEDtve: ${e}`,caution:{spam:`Sok reklám lehet itt. Követés előtt nézz bele.`,"off-topic":`Más témákhoz is használják. Először nézd meg a bejegyzéseket.`},shelves:{youtube:{heading:`YouTube-csatornával rendelkező alkotók`,intro:`Videósok, akik a Mastodonon is írnak.`},notable:{heading:`Alkotók és ismert nevek`,intro:`A témához kapcsolódó szerzők, művészek, kiadványok és szervezetek.`},community:{heading:`Közösségi hangok`,intro:`Aktív emberek, akik írnak a témáról, és engedélyezik profiljuk felfedezését.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube: 10 ezer+`,"followers-2500":`2500+ követő`,"followers-625":`625+ követő`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Podcast`,website:`Weboldal`},choose:[`A friss nyilvános bejegyzések témáját és nyelvét ellenőrizzük. Felfedezhető profilokat vagy igazolhatóan ismert közszereplőket veszünk fel.`,`Kizárjuk az inaktív és átköltözött profilokat. Tiszteletben tartjuk az ajánlás kifejezett tiltását és az eltávolítási kéréseket; az adatvédelmi jelzéseket is figyelembe vesszük.`,`Nyelvi modell segít a szerzők saját bejegyzései alapján ellenőrizni a témához illeszkedést. A válogatást megjelenés előtt átnézzük, de a későbbi bejegyzések témáját nem garantáljuk.`]});var v={lt:s$1(r$1({},i),{eyebrow:`Mastodon pradžios rinkinys`,openApp:`Atverti Mawkingbird`,hub:`Visos bendruomenės`,tagsHeading:`Grotažymės, kurias verta sekti`,tagsIntro:`Mastodon gali sekti ir grotažymes: jų vieši įrašai atsiras tavo pradžios sraute. Kai kurios grotažymės tylios. Prieš sekdamas peržiūrėk jų įrašus.`,englishTag:`Angliškai`,futureHeading:`Padėk šioms grotažymėms prigyti`,futureIntro:`Kai kurios populiarios angliškos grotažymės turi vietinius atitikmenis, kurie tik pradeda gyvuoti. Sek abi ir lietuviškuose įrašuose naudok vietinę grotažymę.`,futureBeside:e=>`vietinis #${e} atitikmuo`,futureNew:`nauja`,futureStarting:`tik pradeda gyvuoti`,youtube:e=>e?`YouTube kanalas, prenumeratoriai: ${e}`:`YouTube kanalas`,feedCopy:`skelbia naujus vaizdo įrašus`,activity:e=>`${e.toLocaleString(`lt`)} \u012Fra\u0161\u0173 \u0161i\u0105 savait\u0119 mastodon.social serveryje`,serversHeading:`Kur renkasi bendruomenė`,serversIntro:`Iš savo Mastodon serverio gali sekti kitų serverių profilius. Jei dar renkiesi serverį, susipažink su šiomis bendruomenėmis ir jų taisyklėmis.`,chooseHeading:`Kaip atrenkame`,helpHeading:`Reikia pagalbos?`,help:`Turi klausimų ar nori pašalinti savo profilį iš rinkinio? Parašyk mums Mastodon.`,helpLink:`@mawkingbird@mastodon.social`,faqHeading:`Dažniausi klausimai`,readTag:e=>`Skaityti #${e} per Mawkingbird`,peopleHeading:`Ką sekti`,groupColumn:`Grupė`,countColumn:`Profiliai`,everyone:`Visi`,alsoYoutubeHeading:`Taip pat YouTube`,alsoYoutubeIntro:(e,a)=>`${e} i\u0161 ${a} profili\u0173 turi YouTube kanalus. Gali sekti autorius Mastodon arba \u017Ei\u016Br\u0117ti vaizdo \u012Fra\u0161us per Mawkingbird.`,otherLanguages:`Šis puslapis kitomis kalbomis`,updated:e=>`Atnaujinta: ${e}`,caution:{spam:`Gali būti daug reklamos. Prieš sekdamas peržiūrėk.`,"off-topic":`Naudojama ir kitoms temoms. Pirmiausia peržiūrėk įrašus.`},shelves:{youtube:{heading:`Autoriai su YouTube kanalais`,intro:`Vaizdo kūrėjai, kurie rašo ir Mastodon.`},notable:{heading:`Autoriai ir žinomi vardai`,intro:`Šios srities rašytojai, menininkai, leidiniai ir organizacijos.`},community:{heading:`Bendruomenės balsai`,intro:`Aktyvūs žmonės, rašantys šia tema ir leidžiantys atrasti savo profilį.`}},fame:{wikidata:`Wikidata`,wikipedia:`Wikipedia`,"youtube-10k":`YouTube: 10 tūkst.+`,"followers-2500":`2500+ sekėjų`,"followers-625":`625+ sekėjų`},elsewhere:{bluesky:`Bluesky`,youtube:`YouTube`,twitch:`Twitch`,patreon:`Patreon`,podcast:`Tinklalaidė`,website:`Svetainė`},choose:[`Tikriname naujausių viešų įrašų temą ir kalbą. Įtraukiame atrandamus profilius arba viešus asmenis, kurių žinomumas pagrįstas patikrinamais duomenimis.`,`Neįtraukiame neaktyvių ar perkeltų profilių. Paisome aiškaus atsisakymo būti siūlomam ir pašalinimo prašymų, taip pat kitų privatumo signalų.`,`Kalbos modelis padeda tikrinti atitiktį pagal pačių autorių įrašus. Rinkinį peržiūrime prieš skelbdami, tačiau negalime garantuoti būsimų įrašų temos.`]}),hu:m,el:k,lv:p,uk:h,nl:c,en:i,de:t,fr:s,es:u,it:r,ja:d,vi:g,ms:l};function f(e){return v[e]??i}export{v as FEED_CHROME,f as chromeFor};